define(['jquery','ko','uiComponent','Magento_Checkout/js/model/quote','Magento_Checkout/js/model/shipping-service','Magento_Checkout/js/action/select-shipping-method','Magento_Checkout/js/checkout-data','mage/translate'],function($,ko,Component,quote,shippingService,selectShippingMethodAction,checkoutData,$t){'use strict';return Component.extend({defaults:{template:'Mab_CheckoutCustomization/shipping-method-cards'},initialize:function(){var self=this;self._super();self.shippingMethods=ko.observableArray([]);self.selectedMethod=ko.observable(null);self.isVisible=ko.observable(true);self.currentRegion=ko.observable(null);self.isLoading=ko.observable(false);console.log('Shipping cards component initialized');shippingService.getShippingRates().subscribe(function(rates){console.log('Shipping rates received:',rates);self.processShippingRates(rates);});quote.shippingMethod.subscribe(function(method){if(method){console.log('Quote shipping method changed:',method);self.selectedMethod(method.carrier_code+'_'+method.method_code);}});quote.shippingAddress.subscribe(function(address){console.log('Address changed:',address);if(address&&(address.regionId||address.region)){var regionName=address.region||'Region '+address.regionId;console.log('Region detected:',regionName);self.currentRegion(regionName);self.isVisible(true);}});var initialRates=shippingService.getShippingRates()();if(initialRates&&initialRates.length>0){console.log('Processing initial rates:',initialRates);self.processShippingRates(initialRates);}
var initialAddress=quote.shippingAddress();console.log('Initial address on init:',initialAddress);if(initialAddress&&(initialAddress.regionId||initialAddress.region)){var regionName=initialAddress.region||'Region '+initialAddress.regionId;console.log('Initial region set:',regionName);self.currentRegion(regionName);self.isVisible(true);}
var currentMethod=quote.shippingMethod();if(currentMethod){console.log('Initial method:',currentMethod);self.selectedMethod(currentMethod.carrier_code+'_'+currentMethod.method_code);}
setTimeout(function(){console.log('Force visibility timeout triggered');self.isVisible(true);var wrapper=document.querySelector('.shipping-methods-cards-wrapper');if(wrapper){wrapper.style.display='block';wrapper.style.visibility='visible';wrapper.style.opacity='1';console.log('Wrapper made visible via DOM manipulation');}else{console.warn('Wrapper element not found!');}},500);return self;},processShippingRates:function(rates){var self=this;var methods=[];console.log('Processing rates, count:',rates.length);rates.forEach(function(rate){console.log('Processing rate:',rate);var method={method_code:rate.carrier_code+'_'+rate.method_code,carrier_code:rate.carrier_code,method_id:rate.method_code,method_title:rate.method_title||rate.carrier_title,amount:parseFloat(rate.amount)||0,price_formatted:self.formatPrice(rate.amount),carrier_logo:self.getCarrierLogo(rate),delivery_time:self.getDeliveryTime(rate),is_free:parseFloat(rate.amount)===0,description:self.getMethodDescription(rate),error_message:rate.error_message||'',available:rate.available!==false};console.log('Created method object:',method);methods.push(method);});console.log('Setting methods array, count:',methods.length);self.shippingMethods(methods);if(methods.length>0){self.isVisible(true);console.log('Methods loaded, setting visible');}},getCarrierLogo:function(rate){var baseUrl='https://dev.technostationery.com/media/mageplaza/tablerate/';var methodCode=rate.method_code;var logoMap={'17':'techno.png','20':'techno.png','24':'yalidine-logo.jpg','2':'yalidine-logo.jpg'};if(rate.image){return rate.image;}
var logo=logoMap[methodCode]||'default-carrier.png';return baseUrl+logo;},getDeliveryTime:function(rate){var methodCode=rate.method_code;var title=(rate.method_title||'').toLowerCase();if(methodCode==='17'||methodCode==='20'||title.includes('retrait techno')){return $t('Retrait immédiat');}else if(methodCode==='24'||title.includes('retrait en agence')){return $t('2-3 jours');}else if(methodCode==='2'||title.includes('livraison')){return $t('3-5 jours');}
return $t('Délai standard');},getMethodDescription:function(rate){var methodCode=rate.method_code;var title=(rate.method_title||'').toLowerCase();var region=this.currentRegion()||'';if(methodCode==='17'||methodCode==='20'||title.includes('retrait techno')){return $t('Retirez votre commande à notre magasin de %1').replace('%1',region);}else if(methodCode==='24'||title.includes('retrait en agence')){return $t('Retrait à l\'agence Yalidine la plus proche');}else if(methodCode==='2'||title.includes('livraison')){return $t('Livraison directement à votre domicile');}
return rate.carrier_title||'';},formatPrice:function(amount){var price=parseFloat(amount)||0;if(price===0){return $t('Gratuit');}
return price.toFixed(0)+' DA';},getShippingMethods:function(){return this.shippingMethods();},selectMethod:function(method){var self=this;console.log('Selecting shipping method:',method);if(!method.available){console.warn('Method not available:',method);return;}
self.selectedMethod(method.method_code);var shippingMethod={carrier_code:method.carrier_code,method_code:method.method_id,carrier_title:method.method_title,method_title:method.method_title,amount:method.amount,base_amount:method.amount,available:true,error_message:'',price_excl_tax:method.amount,price_incl_tax:method.amount};console.log('Calling selectShippingMethodAction with:',shippingMethod);selectShippingMethodAction(shippingMethod);checkoutData.setSelectedShippingRate(method.carrier_code+'_'+method.method_id);},isSelected:function(method){return this.selectedMethod()===method.method_code;},getCardClasses:function(method){var classes='shipping-card';if(this.isSelected(method)){classes+=' selected';}
if(method.is_free){classes+=' free-shipping';}
if(!method.available){classes+=' unavailable';}
return classes;},getRegionName:function(){return this.currentRegion()||$t('votre région');}});});